#!/usr/bin/env node
const fs = require('fs');
const path = require('path');
const Ajv2020 = require('ajv/dist/2020');
const standaloneCode = require('ajv/dist/standalone').default;

const ROOT = path.resolve(__dirname, '..');
const schema = JSON.parse(fs.readFileSync(path.join(ROOT, 'content.schema.json'), 'utf8'));
const ajv = new Ajv2020({ allErrors: true, code: { source: true }, strict: true });
const validate = ajv.compile(schema);
const compiled = standaloneCode(ajv, validate);

const source = `// Generated by scripts/build-content-validator.cjs from content.schema.json.
// Do not edit this file by hand.
(function () {
  'use strict';
  var module = { exports: {} };
  var exports = module.exports;
${compiled.split('\n').map((line) => `  ${line}`).join('\n')}

  function formatError(error) {
    var place = error.instancePath || '(root)';
    if (error.keyword === 'required') {
      return place + ': thiếu trường "' + error.params.missingProperty + '"';
    }
    if (error.keyword === 'additionalProperties') {
      return place + ': trường không hợp lệ "' + error.params.additionalProperty + '"';
    }
    return place + ': ' + error.message;
  }

  window.LotusContentValidator = {
    validate: module.exports,
    errors: function () {
      return (module.exports.errors || []).map(formatError);
    }
  };
})();
`;

fs.writeFileSync(path.join(ROOT, 'admin', 'content-validator.js'), source);
console.log('✓ admin/content-validator.js');
